package backend

import "fmt"

// Item is the stable public item shape.
type Item struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

// ItemsResponse is the public GET /items response.
type ItemsResponse struct {
	Items     []Item `json:"items"`
	NextCursor *string `json:"next_cursor"`
}

// FetchItems serves one page. A nil cursor is the initial page; a non-nil
// cursor is used as the page token exactly as supplied by the caller.
func FetchItems(cursor *string, limit int) (ItemsResponse, error) {
	if limit < 1 {
		return ItemsResponse{}, fmt.Errorf("limit must be at least 1")
	}

	all := []Item{
		{ID: "i1", Name: "one"},
		{ID: "i2", Name: "two"},
		{ID: "i3", Name: "three"},
	}
	start := 0
	if cursor != nil {
		if *cursor != "cursor-2" {
			return ItemsResponse{}, fmt.Errorf("invalid cursor")
		}
		start = 2
	}
	if start >= len(all) {
		return ItemsResponse{Items: []Item{}, NextCursor: nil}, nil
	}
	end := start + limit
	if end > len(all) {
		end = len(all)
	}
	response := ItemsResponse{Items: all[start:end]}
	if end < len(all) {
		next := fmt.Sprintf("cursor-%d", end)
		response.NextCursor = &next
	}
	return response, nil
}

// PageRequester represents a request to GET /items.
type PageRequester func(cursor *string, limit int) (ItemsResponse, error)

// CollectItems requests pages until the server returns a null next_cursor.
// Each subsequent request receives the exact cursor returned by the prior page.
func CollectItems(request PageRequester, limit int) ([]Item, error) {
	if limit < 1 {
		return nil, fmt.Errorf("limit must be at least 1")
	}
	var cursor *string
	var collected []Item
	for {
		page, err := request(cursor, limit)
		if err != nil {
			return nil, err
		}
		collected = append(collected, page.Items...)
		if page.NextCursor == nil {
			return collected, nil
		}
		next := *page.NextCursor
		cursor = &next
	}
}

